// The original 2.4 s clip is embedded so the two release channels can load it offline.
(function () {
  'use strict';
  const movie = 'data:video/mp4;base64,';
  const alternate = 'data:image/webp;base64,';
  const chime = '';
  let audio, decodedChime;

  function prepare() {
    const video = document.createElement('video');
    video.playsInline = true;
    video.disablePictureInPicture = true;
    video.preload = 'auto';
    video.volume = .4;
    video.setAttribute('aria-hidden', 'true');
    video.src = movie;
    // Unlock original chime playback during the click for browsers that require muted video.
    try {
      const Audio = window.AudioContext || window.webkitAudioContext;
      if (Audio) {
        audio ||= new Audio();
        audio.resume().catch(() => {});
        decodedChime ||= audio.decodeAudioData(Uint8Array.from(atob(chime), c => c.charCodeAt(0)).buffer).catch(() => null);
      }
    } catch { /* Native soundtrack remains available. */ }
    return video;
  }

  async function play(button, video) {
    let finished = false, playedChime = false, soundSource;
    function originalChime() {
      if (playedChime || !decodedChime || audio.state !== 'running') return;
      playedChime = true;
      decodedChime.then(buffer => {
        if (!buffer || finished) return;
        soundSource = audio.createBufferSource();
        soundSource.buffer = buffer;
        const gain = audio.createGain();
        gain.gain.value = .4;
        soundSource.connect(gain).connect(audio.destination);
        soundSource.onended = () => { soundSource.disconnect(); gain.disconnect(); };
        soundSource.start();
      }).catch(() => {});
    }

    button.replaceChildren(video);
    let watchdog, raf;
    const controller = new AbortController();
    const options = {signal:controller.signal};
    const ended = await new Promise(resolve => {
      const settle = ok => { clearTimeout(watchdog); resolve(ok); };
      function arm() {
        clearTimeout(watchdog);
        if (!document.hidden) watchdog = setTimeout(() => settle(false), 3500);
      }
      const clock = () => {
        if (video.muted && video.currentTime >= .57) originalChime();
        raf = requestAnimationFrame(clock);
      };
      video.addEventListener('ended', () => settle(true), options);
      video.addEventListener('error', () => settle(false), options);
      video.addEventListener('timeupdate', arm, options);
      document.addEventListener('visibilitychange', arm, options);
      arm();
      raf = requestAnimationFrame(clock);
      video.play().catch(error => {
        if (error.name !== 'NotAllowedError') { settle(false); return; }
        video.muted = true;
        video.play().catch(() => settle(false));
      });
    });
    controller.abort();
    cancelAnimationFrame(raf);
    clearTimeout(watchdog);
    video.pause();

    if (!ended) {
      // Keep the drawing visible even when the device cannot decode H.264.
      if (!video.muted && video.currentTime >= .57) playedChime = true;
      const image = new Image();
      image.alt = '';
      image.src = alternate;
      button.replaceChildren(image);
      const timer = setTimeout(originalChime, 570);
      await new Promise(resolve => setTimeout(resolve, 2400));
      clearTimeout(timer);
    }
    finished = true;
  }

  window.LeavesLoginVideo = {prepare, play};
})();
